formulas.expression:
IF(
   NOT( ISBLANK( {!field_ERCEventDate} ) ), {!field_ERCEventDate},
   IF(
      NOT( ISBLANK( {!field_inputEventDate} ) ), {!field_inputEventDate},
      IF(
         NOT( ISBLANK( {!field_needByDate} ) ), {!field_needByDate},
         IF(
            NOT( ISBLANK( {!field_idealDueDate} ) ), {!field_idealDueDate},
            IF(
               NOT( ISBLANK( {!field_employeeStartEndDate} ) ), {!field_employeeStartEndDate},
               IF(
                  NOT( ISBLANK( {!field_meetingDate} ) ), {!field_meetingDate},
                    IF(
                        NOT( ISBLANK( {!field_dueDate} ) ), {!field_dueDate},
                  null
                )
              )
            )
         )
      )
   )
)
